pub fn run() -> Vec<String> {
    let mut names = vec![String::from("ada"), String::from("grace")];

    for n in names.iter() {
        if n.len() == 3 {
            names.push(format!("{n}!"));
        }
    }

    names
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn appends_the_short_ones() {
        assert_eq!(run(), vec!["ada", "grace", "ada!"]);
    }
}

exercises.solution:
pub fn run() -> Vec<String> {
    let mut names = vec![String::from("ada"), String::from("grace")];

    let extra: Vec<String> = names
        .iter()
        .filter(|n| n.len() == 3)
        .map(|n| format!("{n}!"))
        .collect();

    names.extend(extra);
    names
}

exercises.starter:
pub struct Evens {
    src: &[i32],
    i: usize,
}

impl Iterator for Evens {
    type Item = i32;

    fn next(&mut self) -> Option<i32> {
        while self.i < self.src.len() {
            let x = self.src[self.i];
            self.i += 1;
            if x % 2 == 0 {
                return Some(x);
            }
        }
        None
    }
}

pub fn evens(src: &[i32]) -> Evens {
    Evens { src, i: 0 }
}

pub fn run() -> (Vec<i32>, i32) {
    let data = [1, 2, 3, 4, 6, 7];
    let v: Vec<i32> = evens(&data).collect();
    let s: i32 = evens(&data).map(|x| x * 10).sum();
    (v, s)
}

